 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_67", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_69", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_71", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_73", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_75", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_76", fn: function(){ return (!(((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_61", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_45", fn: function(){ return ((dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1'); } }, { id: "img_94", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_96", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_98", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_100", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_102", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_103", fn: function(){ return (!(((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm_2", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_88", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "btn_modify", fn: function(){ return (((dlt_bbsList.getCellData(0, "wrtrId") ?? (() => { throw new Error("unresolved:" + "entity.wrtrId"); })()) !== (dma_commonInfo.get("empNo") ?? (() => { throw new Error("unresolved:" + "commonInfo.empNo"); })()))); } }, { id: "btn_delete", fn: function(){ return (((dlt_bbsList.getCellData(0, "wrtrId") ?? (() => { throw new Error("unresolved:" + "entity.wrtrId"); })()) !== (dma_commonInfo.get("empNo") ?? (() => { throw new Error("unresolved:" + "commonInfo.empNo"); })()))); } }, { id: "c_when_79", fn: function(){ return ((dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '2'); } }, { id: "btn_modify_2", fn: function(){ return ((((dma_pageContext.get("bbsList") ?? "")) && typeof ((dma_pageContext.get("bbsList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("bbsList") ?? "")).getRowCount() : ((((dma_pageContext.get("bbsList") ?? "")) == null) ? 0 : (((dma_pageContext.get("bbsList") ?? "")).length || 0))) === 1 && (dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_bbsList.getCellData(0, "isurCd") ?? (() => { throw new Error("unresolved:" + "entity.isurCd"); })()) === (dma_session.get("isurCd") ?? (() => { throw new Error("unresolved:" + "session.company.isurCd"); })())); } }, { id: "btn_delete_2", fn: function(){ return ((((dma_pageContext.get("bbsList") ?? "")) && typeof ((dma_pageContext.get("bbsList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("bbsList") ?? "")).getRowCount() : ((((dma_pageContext.get("bbsList") ?? "")) == null) ? 0 : (((dma_pageContext.get("bbsList") ?? "")).length || 0))) === 1 && (dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_bbsList.getCellData(0, "isurCd") ?? (() => { throw new Error("unresolved:" + "entity.isurCd"); })()) === (dma_session.get("isurCd") ?? (() => { throw new Error("unresolved:" + "session.company.isurCd"); })())); } }, { id: "c_when_40", fn: function(){ return (!(String(((dma_pageContext.get("bbsList") ?? "")) == null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
