 */
scwin.tx_fn_reply = async function (action) {
    const sbmOptions = {
        id: "tx_fn_reply",
        method: "post",
        action: action ?? "/konex/bbs.do",
        ref: "dma_replyReq",
        target: "dlt_bbsList=body.content",
