/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name changePage
 * @description change Page 처리
 * @param {*} ver1 ver1
 * @param {*} ver2 ver2
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changePage = async function (ver1, ver2) {
    const form = (document.moveForm || { elements: [] });
    if ('1' === ver1) {
        $c.util.getComponent('dma_changePageReq').set('nowPage', ver2);
    } else {
        if ('2' === ver1) {
            $c.util.getComponent('dma_changePageReq').set('nowPage', '20');
            $c.util.getComponent("dma_changePageReq").set("method", 'loadDetail');
        } else {
            if ('3' === ver1) {
                $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
                form.action = '/konex/bbs.do';
                $c.util.getComponent("dma_changePageReq").set("method", 'searchCommentLetterList');
            } else {
                if ('4' === ver1) {
                    $c.util.getComponent('dma_changePageReq').set('nowPage', '40');
                }
            }
        }
    }
    await scwin.tx_changePage();
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    $c.util.getComponent("dma_changePageReq").set("method", 'searchCommentLetterList');
    $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
    const nr = await scwin.tx_fn_goList('/konex/bbs.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil51300/jldfil51300.xml", { "method": 'searchCommentLetterList', "nowPage": '30' });
    }
};

